Use ASP.NET Core's **`WebApplicationFactory<TEntryPoint>`** from `Microsoft.AspNetCore.Mvc.Testing`. It spins up your app in-memory with a test `HttpClient` — no ports, no real server.

### Setup

```bash
dotnet add <YourTestProject> package Microsoft.AspNetCore.Mvc.Testing
```

### Example test class

```csharp
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.AspNetCore.Mvc.Testing;
using Xunit;

public class McpIntegrationTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly HttpClient _client;

    public McpIntegrationTests(WebApplicationFactory<Program> factory)
    {
        _client = factory.CreateClient();
    }

    [Fact]
    public async Task Initialize_ReturnsCapabilities()
    {
        var request = new
        {
            jsonrpc = "2.0",
            id = 1,
            method = "initialize",
            @params = new
            {
                protocolVersion = "2025-03-26",
                capabilities = new { },
                clientInfo = new { name = "test-client", version = "1.0" }
            }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal("2.0", body.GetProperty("jsonrpc").GetString());
        Assert.True(body.TryGetProperty("result", out var result));
        Assert.True(result.TryGetProperty("capabilities", out _));
    }

    [Fact]
    public async Task ToolsList_ReturnsRegisteredTools()
    {
        var request = new { jsonrpc = "2.0", id = 2, method = "tools/list" };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        var tools = body.GetProperty("result").GetProperty("tools");
        Assert.True(tools.GetArrayLength() > 0);
    }

    [Fact]
    public async Task ToolsCall_ExecutesTool()
    {
        var request = new
        {
            jsonrpc = "2.0",
            id = 3,
            method = "tools/call",
            @params = new
            {
                name = "your-tool-name",
                arguments = new { /* tool-specific args */ }
            }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        Assert.False(body.TryGetProperty("error", out _));
    }
}
```

### Key points

- **`/mcp`** — adjust to match your actual MCP endpoint path.
- **`Program`** must be accessible — add `<InternalsVisibleTo Include="YourTestProject" />` to your server's `.csproj`, or use a public partial class.
- **SSE (Streamable HTTP)**: If your server uses SSE responses, read the stream manually:
  ```csharp
  var stream = await response.Content.ReadAsStreamAsync();
  using var reader = new StreamReader(stream);
  while (await reader.ReadLineAsync() is { } line)
  {
      // parse "data: {...}" lines
  }
  ```
- **Override services** for isolation (e.g., mock a database):
  ```csharp
  factory.WithWebHostBuilder(builder =>
  {
      builder.ConfigureServices(services =>
      {
          services.AddSingleton<IMyDep>(new FakeDep());
      });
  });
  ```

This gives you full HTTP-level integration tests covering serialization, routing, middleware, and MCP protocol compliance — all in-process.
